		/**
		 * Returns a new populated Alert
		 * 
		 * @return Alert
		 */
		protected Alert generateNewEntity() {
			Alert entity = new Alert( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  null,  null,  null,  null,  new HashSet<>(),  new HashSet<>(),  AlertSeverity.values()[0],  AlertStatus.values()[0] );
			
			return( entity );
		}

